CREATE TEMP TABLE lesson_ledger_accounts (
 merchant_id INTEGER NOT NULL, account_id INTEGER NOT NULL,
 currency TEXT NOT NULL CHECK (currency = 'IDR'),
 PRIMARY KEY (merchant_id, account_id, currency)
);
CREATE TEMP TABLE lesson_ledger_transfers (
 merchant_id INTEGER NOT NULL, business_key TEXT NOT NULL,
 currency TEXT NOT NULL CHECK (currency = 'IDR'),
 payload_fingerprint TEXT NOT NULL,
 PRIMARY KEY (merchant_id, business_key),
 UNIQUE (merchant_id, business_key, currency)
);
CREATE TEMP TABLE lesson_ledger_entries (
 merchant_id INTEGER NOT NULL, business_key TEXT NOT NULL,
 line_no INTEGER NOT NULL CHECK (line_no IN (1, 2)),
 account_id INTEGER NOT NULL, currency TEXT NOT NULL,
 amount BIGINT NOT NULL CHECK (amount BETWEEN -1000000000000 AND 1000000000000 AND amount <> 0),
 PRIMARY KEY (merchant_id, business_key, line_no),
 FOREIGN KEY (merchant_id, business_key, currency)
 REFERENCES pg_temp.lesson_ledger_transfers (merchant_id, business_key, currency),
 FOREIGN KEY (merchant_id, account_id, currency)
 REFERENCES pg_temp.lesson_ledger_accounts (merchant_id, account_id, currency)
);
CREATE TEMP TABLE lesson_ledger_outbox (
 merchant_id INTEGER NOT NULL, business_key TEXT NOT NULL,
 event_kind TEXT NOT NULL CHECK (event_kind = 'transfer_posted'),
 PRIMARY KEY (merchant_id, business_key),
 FOREIGN KEY (merchant_id, business_key)
 REFERENCES pg_temp.lesson_ledger_transfers (merchant_id, business_key)
);
CREATE TEMP TABLE lesson_ledger_audit (
 merchant_id INTEGER NOT NULL, business_key TEXT NOT NULL,
 actor_id TEXT NOT NULL, action TEXT NOT NULL CHECK (action = 'post'),
 PRIMARY KEY (merchant_id, business_key),
 FOREIGN KEY (merchant_id, business_key)
 REFERENCES pg_temp.lesson_ledger_transfers (merchant_id, business_key)
);
